 3	function bullspec(s:seq<nat>, u:seq<nat>): nat
 4	requires 0 <= |u| == |s| && nomultiples(u)
 5	{reccbull(s, u, 0)}
 6	
 7	function cowspec(s:seq<nat>, u:seq<nat>): nat
 8	requires nomultiples(u)
 9	{recccow(s, u, 0)}
10	
11	function reccbull(s: seq<nat>, u:seq<nat>, i:int): nat
12	requires 0 <= i <= |s| == |u|
13	decreases |s| - i
14	{
15	    if i ==|s| then 0
16	    else if s[i] == u[i] then reccbull(s, u, i + 1) + 1
17	    else reccbull(s, u, i + 1)
18	}
19	
20	function recccow(s: seq<nat>, u:seq<nat>, i:int): nat
21	requires 0 <= i <= |s| == |u|
22	decreases |s| - i
23	{
24	    if i == |s| then 0
25	    else if s[i] != u[i] && u[i] in s then recccow(s, u, i + 1) + 1
26	    else recccow(s, u, i + 1)
27	}
28	
29	predicate nomultiples(u:seq<nat>) 
30	{forall j, k :: 0<=j<k<|u| ==> u[j] != u[k]}
31	
32	method BullsCows (s:seq<nat>, u:seq<nat>) returns (b:nat, c:nat) 
33	requires 0 < |u| == |s| <= 10
34	requires nomultiples(u) && nomultiples(s);
35	ensures b >= 0 && c >= 0
36	ensures b == bullspec(s, u)
37	ensures c == cowspec(s, u)
38	{
39	    b, c := 0, 0;
40	    var i:int := |s|;
41	
42	    while i > 0
43	    invariant  0 <= i <= |s| == |u|
44	    invariant b >= 0 && c >= 0
45	    invariant b == reccbull(s,u, i)
46	    invariant c == recccow(s, u, i)
47	    decreases i
48	    {
49	        i := i - 1;
50	        if s[i] != u[i] && u[i] in s {c:= c + 1;}
51	        else if s[i] == u[i] {b := b + 1;}
52	    }
53	
54	    return b, c;
55	}
56	
57	method TEST(){
58	    var sys:seq<nat> := [1,2,9,10];
59	    var usr:seq<nat> := [1,2,3,7];
60	
61	    assert bullspec(sys, usr) == 2;
62	    assert cowspec(sys, usr) == 0;
63	
64	    var b:nat, c:nat := BullsCows(sys, usr);
65	    assert b == 2 && c == 0;
66	
67	    var sys1:seq<nat> := [1, 2, 3, 4];
68	    var usr2:seq<nat> := [4, 3, 2, 1];
69	
70	    assert bullspec(sys1, usr2) == 0;
71	    assert cowspec(sys1, usr2) == 4;
72	
73	    b, c := BullsCows(sys1, usr2);
74	    assert b == 0 && c == 4;
75	
76	    var sys3:seq<nat> := [1, 2, 3, 4, 5, 6, 7];
77	    var usr3:seq<nat> := [1, 2, 3, 4, 5, 6, 7];
78	
79	    assert bullspec(sys3, usr3) == 7;
80	    assert cowspec(sys3, usr3) == 0;
81	
82	    b, c := BullsCows(sys3, usr3);
83	    assert b == 7 && c == 0;
84	
85	    var sys4:seq<nat> := [1, 2, 3, 4, 5, 6, 7];
86	    var usr4:seq<nat> := [1, 2, 3, 7, 8, 6, 5];
87	
88	    assert bullspec(sys4, usr4) == 4;
89	    assert cowspec(sys4, usr4) == 2;
90	
91	    b, c := BullsCows(sys4, usr4);
92	}

